package co.sena.academic.adapter.in.rest;
import co.sena.academic.adapter.in.rest.dto.*; import co.sena.academic.adapter.in.rest.mapper.LearningOutcomeRestMapper; import co.sena.academic.application.port.in.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/v1") public class LearningOutcomeController {private final CreateLearningOutcomeUseCase create;private final UpdateLearningOutcomeUseCase update;private final DeactivateLearningOutcomeUseCase deactivate;private final QueryLearningOutcomesUseCase query;private final LearningOutcomeRestMapper mapper; public LearningOutcomeController(CreateLearningOutcomeUseCase create,UpdateLearningOutcomeUseCase update,DeactivateLearningOutcomeUseCase deactivate,QueryLearningOutcomesUseCase query,LearningOutcomeRestMapper mapper){this.create=create;this.update=update;this.deactivate=deactivate;this.query=query;this.mapper=mapper;}
@PostMapping("/competencies/{competencyId}/learning-outcomes") @PreAuthorize("hasAuthority('ACADEMIC_PROGRAM_MANAGE')") public ResponseEntity<LearningOutcomeResponse> create(@PathVariable UUID competencyId,@Valid @RequestBody CreateLearningOutcomeRequest r,@AuthenticationPrincipal UUID actor){var body=mapper.toResponse(create.create(new CreateLearningOutcomeUseCase.Command(competencyId,r.code(),r.description(),r.isActive(),actor)));return ResponseEntity.created(URI.create("/competencies/"+competencyId+"/learning-outcomes")).body(body);}
@GetMapping("/competencies/{competencyId}/learning-outcomes") @PreAuthorize("hasAuthority('ACADEMIC_PROGRAM_VIEW')") public ResponseEntity<LearningOutcomePageResponse> list(@PathVariable UUID competencyId,@RequestParam(value="is_active",required=false) Boolean active,@RequestParam(defaultValue="1") @Min(1) int page,@RequestParam(name="page_size",defaultValue="20") @Min(1) @Max(100) int pageSize,@RequestParam(required=false) String sort){return ResponseEntity.ok(mapper.toPageResponse(query.list(new QueryLearningOutcomesUseCase.Query(competencyId,Optional.ofNullable(active),page-1,pageSize,Optional.ofNullable(sort)))));}
@PutMapping("/learning-outcomes/{id}") @PreAuthorize("hasAuthority('ACADEMIC_PROGRAM_MANAGE')") public ResponseEntity<LearningOutcomeResponse> update(@PathVariable UUID id,@Valid @RequestBody UpdateLearningOutcomeRequest r,@AuthenticationPrincipal UUID actor){return ResponseEntity.ok(mapper.toResponse(update.update(new UpdateLearningOutcomeUseCase.Command(id,r.code(),r.description(),r.isActive(),r.rowVersion(),actor))));}
@DeleteMapping("/learning-outcomes/{id}") @PreAuthorize("hasAuthority('ACADEMIC_PROGRAM_MANAGE')") public ResponseEntity<Void> delete(@PathVariable UUID id,@AuthenticationPrincipal UUID actor){deactivate.deactivate(new DeactivateLearningOutcomeUseCase.Command(id,actor));return ResponseEntity.noContent().build();}}
